function sk1370_conversations(int $uid): array { $q=sk1370_db()->prepare("SELECT c.*,a.title,a.slug,a.status ad_status FROM classified_conversations_v1370 c JOIN classified_ads_v1370 a ON a.id=c.ad_id AND a.tenant_id=c.tenant_id WHERE c.tenant_id=? AND (c.buyer_user_id=? OR c.seller_user_id=?) ORDER BY c.last_message_at DESC,c.id DESC LIMIT 100");$q->execute([sk1370_tid(),$uid,$uid]);return $q->fetchAll(PDO::FETCH_ASSOC)?:[]; }
function sk1370_messages(int $conversationId,int $uid): array { $q=sk1370_db()->prepare('SELECT 1 FROM classified_conversations_v1370 WHERE tenant_id=? AND id=? AND (buyer_user_id=? OR seller_user_id=?)');$q->execute([sk1370_tid(),$conversationId,$uid,$uid]);if(!$q->fetchColumn())throw new RuntimeException('Conversation not found.');$m=sk1370_db()->prepare('SELECT * FROM classified_messages_v1370 WHERE tenant_id=? AND conversation_id=? AND deleted_at IS NULL ORDER BY id ASC LIMIT 300');$m->execute([sk1370_tid(),$conversationId]);return $m->fetchAll(PDO::FETCH_ASSOC)?:[]; }
function sk1370_import_legacy(): array { if(!sk1370_admin())throw new RuntimeException('Admin access required.');$pdo=sk1370_db();$tid=sk1370_tid();$sources=['marketplace_listings','marketplace_items','listings','classifieds'];$stats=['found'=>0,'imported'=>0,'skipped'=>0,'sources'=>[]];$otherQ=$pdo->prepare("SELECT id FROM classified_categories_v1370 WHERE tenant_id IN(0,?) AND slug='other' ORDER BY tenant_id DESC LIMIT 1");$otherQ->execute([$tid]);$other=(int)$otherQ->fetchColumn();if(!$other)throw new RuntimeException('Other category is missing.');foreach($sources as $table){if(!sk1370_table($table))continue;$cols=sk1370_cols($table);$idcol=isset($cols['id'])?'id':(isset($cols['listing_id'])?'listing_id':null);$titlecol=null;foreach(['title','name','listing_title'] as $x)if(isset($cols[$x])){$titlecol=$x;break;}if(!$idcol||!$titlecol)continue;$select=[$idcol.' AS legacy_id',$titlecol.' AS legacy_title'];$map=[];foreach(['description','details','body','price','amount','user_id','seller_id','owner_id','area','location','city','status','image','image_url','cover_image','featured_image','thumbnail','category','category_name'] as $x)if(isset($cols[$x])){$select[]='`'.$x.'`';$map[$x]=1;}$sql='SELECT '.implode(',',$select).' FROM `'.$table.'` LIMIT 1000';$rows=$pdo->query($sql)?->fetchAll(PDO::FETCH_ASSOC)?:[];$stats['found']+=count($rows);$stats['sources'][$table]=['found'=>count($rows),'imported'=>0];foreach($rows as $r){$src=(string)$r['legacy_id'];$du=$pdo->prepare('SELECT 1 FROM classified_ads_v1370 WHERE tenant_id=? AND source_table=? AND source_id=? LIMIT 1');$du->execute([$tid,$table,$src]);if($du->fetchColumn()){$stats['skipped']++;continue;}$title=trim((string)$r['legacy_title']);$desc='';foreach(['description','details','body'] as $x)if(!empty($r[$x])){$desc=trim((string)$r[$x]);break;}if($title===''||$desc===''){$stats['skipped']++;continue;}try{sk1370_validate_content($title,$desc);}catch(Throwable $e){$stats['skipped']++;continue;}$uid=0;foreach(['user_id','seller_id','owner_id'] as $x)if(isset($r[$x])&&(int)$r[$x]>0){$uid=(int)$r[$x];break;}if($uid<1)$uid=sk1370_uid();$price=0.0;foreach(['price','amount'] as $x)if(isset($r[$x])&&is_numeric($r[$x])){$price=max(0,(float)$r[$x]);break;}$area='Shahkot';foreach(['area','location','city'] as $x)if(!empty($r[$x])){$area=substr(trim((string)$r[$x]),0,190);break;}$statusRaw=strtolower((string)($r['status']??''));$approved=in_array($statusRaw,['active','published','approved','live','1'],true);$status=$approved?'active':'pending';$mod=$approved?'approved':'pending';$slug=sk1370_unique_slug($title);$pdo->prepare("INSERT INTO classified_ads_v1370(tenant_id,user_id,category_id,title,slug,description,price,price_type,currency,condition_code,city,area,contact_preference,status,moderation_status,bump_at,expires_at,published_at,source_table,source_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'fixed','PKR','used','Shahkot',?,'chat',?,?,NOW(),DATE_ADD(NOW(),INTERVAL 30 DAY),?, ?,?,NOW(),NOW())")->execute([$tid,$uid,$other,$title,$slug,$desc,$price,$area,$status,$mod,$approved?date('Y-m-d H:i:s'):null,$table,$src]);$newId=(int)$pdo->lastInsertId();$image='';foreach(['image','image_url','cover_image','featured_image','thumbnail'] as $x)if(!empty($r[$x])){$image=trim((string)$r[$x]);break;}if($image!==''&&!preg_match('~^https?://~i',$image)){if($image[0]!=='/')$image='/'.ltrim($image,'/');if(preg_match('~^/(?:uploads|storage)/~',$image))$pdo->prepare("INSERT INTO classified_ad_media_v1370(tenant_id,ad_id,file_path,media_type,sort_order,is_cover,created_at) VALUES(?,?,?,'image',0,1,NOW())")->execute([$tid,$newId,$image]);}$stats['imported']++;$stats['sources'][$table]['imported']++;}}return $stats;}
