function sk1370_ad_card(array $a): void { $img=sk1370_cover((int)$a['id']);$featured=!empty($a['featured_until'])&&strtotime((string)$a['featured_until'])>time();$urgent=!empty($a['urgent_until'])&&strtotime((string)$a['urgent_until'])>time();?><article class="skc-card<?=$featured?' featured':''?>"><a class="photo" href="/classified.php?ad=<?=urlencode($a['slug'])?>"><?php if($img):?><img src="<?=sk1370_h($img)?>" loading="lazy" alt=""><?php else:?><span class="no-photo">No photo</span><?php endif;?><?php if($featured):?><i>FEATURED</i><?php endif;?></a><div class="card-body"><div class="price"><?=sk1370_h(sk1370_price_label($a))?></div><a class="title" href="/classified.php?ad=<?=urlencode($a['slug'])?>"><?=sk1370_h($a['title'])?></a><p><?=sk1370_h($a['area'])?> · <?=sk1370_h($a['category_name']??'Classified')?></p><footer><span><?=sk1370_h(date('d M',strtotime((string)$a['published_at'])))?></span><?php if($urgent):?><b>URGENT</b><?php endif;?></footer></div></article><?php }
